{
  "name": "zfr-magpie",
  "version": "0.0.1",
  "description": "Self-contained Magpie provider plugin: zfr-core multi-egress IP rotation, OpenCode v2.1.3 protocol fingerprint, cooldown failover — pure JS/TS, no Rust, no sidecar, no gateway.",
  "type": "module",
  "main": "./index.mjs",
  "exports": {
    ".": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "src/",
    "README.md",
    "LICENSE",
    "NOTICE",
    "assets/icon.svg",
    "assets/icon.png",
    "assets/icon-128.png"
  ],
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "zfr",
    "zfr-core",
    "zen",
    "kilo",
    "egress-rotation",
    "failover"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/ksmord/zfr-magpie"
  },
  "bugs": {
    "url": "https://github.com/ksmord/zfr-magpie/issues"
  },
  "scripts": {
    "check": "node --check index.mjs && node --check src/catalog.mjs && node --check src/constants.mjs && node --check src/egress.mjs && node --check src/fingerprint.mjs && node --check src/netutil.mjs && node --check src/plugin.mjs && node --check src/router.mjs && node --check src/sse.mjs && node --check src/transport.mjs",
    "test": "node test/test-unit.mjs",
    "upstream": "node scripts/check-upstream.mjs"
  },
  "magpie": {
    "maxConcurrency": 2,
    "upstream": "wayne091106-hash/zfr-core"
  }
}
